//===- CoroRuntimeSources.cpp - Embedded coroutine runtime ----------------===//

#include "csl-mlir/Dialect/CSL/Utils/CoroRuntimeSources.h"

#include "llvm/Support/ErrorHandling.h"

// Generated by EmbedCslSource.cmake from the .csl files under
// lib/Dialect/TypedCSL/Transforms/Fiber/runtime/.
#include "resources.csl.inc"
#include "wse2.csl.inc"
#include "wse3.csl.inc"

using namespace mlir::csl;

llvm::StringRef mlir::csl::getFiberRuntimeSource(TargetArch arch) {
  switch (arch) {
  case TargetArch::WSE2:
    return kFiberRuntimeWse2;
  case TargetArch::WSE3:
    return kFiberRuntimeWse3;
  }
  llvm_unreachable("unhandled TargetArch");
}

llvm::StringRef mlir::csl::getAllocRuntimeSource() { return kAllocRuntime; }

bool mlir::csl::isCoroRuntimeImportPath(llvm::StringRef modulePath) {
  return modulePath == kFiberRuntimeImportPath ||
         modulePath == kAllocRuntimeImportPath;
}

llvm::StringRef mlir::csl::getCoroRuntimeSource(llvm::StringRef modulePath,
                                                TargetArch arch) {
  if (modulePath == kFiberRuntimeImportPath)
    return getFiberRuntimeSource(arch);
  if (modulePath == kAllocRuntimeImportPath)
    return getAllocRuntimeSource();
  llvm_unreachable("not a coro runtime import path");
}
